\operatorname{RenR}_{IFP}(\operatorname{ifp}(T,\vec x,\varphi,\vec t),R,S)
=
\begin{cases}
\operatorname{ifp}(T,\vec x,\varphi,\vec t),&T=R,\\
\operatorname{ifp}(T,\vec x,\operatorname{RenR}_{IFP}(\varphi,R,S),\vec t),&T\ne R.
\end{cases}

\cup
\{(\operatorname{ifp}(R,\vec x,\varphi,\vec t),
\operatorname{ifp}(S,\vec z,\operatorname{SubVec}_{IFP}(\operatorname{RenR}_{IFP}(\varphi,R,S),\vec x,\vec z),\vec t)):
\exists n\in\mathbb N\,
(R,S\in\mathsf{RVar}_n
\land \vec x,\vec z:n\to\mathsf{Var}
\land \vec t:n\to\mathsf{Tm}_{IFP}^{\Sigma}
\land \varphi\in\mathsf{Fm}_{IFP}^{\Sigma}
\land S\notin(\operatorname{FRV}(\varphi)\setminus\{R\})\cup\operatorname{BRV}_{IFP}(\varphi)\cup\{R\}
\land \vec z\ \text{单射}
\land \operatorname{rng}(\vec z)\cap\operatorname{rng}(\vec x)=\varnothing
\land
\operatorname{rng}(\vec z)\cap(\operatorname{FV}(\varphi)\setminus\operatorname{rng}(\vec x))=\varnothing)\}.
